  is_delete TINYINT(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0 未删除，1 已删除',
  app_name VARCHAR(64) NOT NULL COMMENT '应用级数据隔离键',
  PRIMARY KEY(id),
  KEY idx_message_app_user(app_name,user_id,is_delete),
