-- 4. 为历史数据库中的系统管理员补齐 root 权限。
INSERT IGNORE INTO yak_security_role_permission(role_id,permission_id,app_name)
SELECT role_row.id,permission_row.id,role_row.app_name
FROM yak_security_role role_row
JOIN yak_security_permission permission_row
  ON permission_row.permission_code='security:root'
 AND permission_row.app_name=role_row.app_name
 AND permission_row.is_delete=0
WHERE role_row.role_name='系统管理员'
  AND role_row.app_name='${appName}'
  AND role_row.is_delete=0;

-- 5. 根据已有读取权限回填系统菜单，升级后不丢失原页面入口。
INSERT IGNORE INTO yak_security_role_menu(role_id,menu_id,app_name)
SELECT DISTINCT role_permission.role_id,menu_row.id,role_permission.app_name
FROM yak_security_role_permission role_permission
JOIN yak_security_permission permission_row
  ON permission_row.id=role_permission.permission_id
 AND permission_row.app_name=role_permission.app_name
 AND permission_row.is_delete=0
JOIN yak_security_menu menu_row
  ON menu_row.required_permission_code=permission_row.permission_code
 AND menu_row.app_name=role_permission.app_name
 AND menu_row.parent_code='system'
 AND menu_row.is_delete=0
WHERE role_permission.app_name='${appName}'
  AND role_permission.is_delete=0;

-- 6. root 角色拥有完整的 Yak Security 系统管理菜单。
INSERT IGNORE INTO yak_security_role_menu(role_id,menu_id,app_name)
SELECT DISTINCT role_permission.role_id,menu_row.id,role_permission.app_name
FROM yak_security_role_permission role_permission
JOIN yak_security_permission permission_row
  ON permission_row.id=role_permission.permission_id
 AND permission_row.app_name=role_permission.app_name
 AND permission_row.permission_code='security:root'
 AND permission_row.is_delete=0
JOIN yak_security_menu menu_row
  ON menu_row.app_name=role_permission.app_name
 AND (menu_row.menu_code='system' OR menu_row.parent_code='system')
 AND menu_row.is_delete=0
WHERE role_permission.app_name='${appName}'
  AND role_permission.is_delete=0;

-- Source: data-ops-framework/data-security/src/main/resources/yak-security/db/migration/V2__link_permissions_to_menus.sql
-- Yak Security 基础表结构迁移必须先于宿主应用的业务权限目录执行。
-- 为权限增加所属菜单编码，明确“菜单控制页面、按钮控制操作”的包含关系。
ALTER TABLE yak_security_permission
  ADD COLUMN menu_code VARCHAR(128) NULL COMMENT '所属稳定菜单编码；按钮权限会自动包含该菜单访问能力' AFTER description;

CREATE INDEX idx_permission_app_menu
  ON yak_security_permission(app_name, menu_code, active, is_delete);

-- Yak Security 自有系统权限与系统菜单绑定。
UPDATE yak_security_permission
SET menu_code='system-users'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:user:%';

UPDATE yak_security_permission
SET menu_code='system-roles'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:role:%';

UPDATE yak_security_permission
SET menu_code='system-permissions'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:permission:%';

UPDATE yak_security_permission
SET menu_code='system-departments'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:department:%';

UPDATE yak_security_permission
SET menu_code='system-security-projects'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:project:%';

UPDATE yak_security_permission
SET menu_code='system-resource-permissions'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:resource-permission:%';

UPDATE yak_security_permission
SET menu_code='system-configs'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:config:%';

UPDATE yak_security_permission
SET menu_code='system-operation-logs'
WHERE app_name='${appName}'
  AND is_delete=0
  AND permission_code LIKE 'security:operation-log:%';

-- 已有角色如果具备页面下任一按钮权限，自动补齐对应菜单。
INSERT IGNORE INTO yak_security_role_menu(role_id,menu_id,app_name)
SELECT DISTINCT role_permission.role_id,menu_row.id,role_permission.app_name
FROM yak_security_role_permission role_permission
JOIN yak_security_permission permission_row
  ON permission_row.id=role_permission.permission_id
 AND permission_row.app_name=role_permission.app_name
 AND permission_row.is_delete=0
 AND permission_row.active=1
 AND permission_row.menu_code IS NOT NULL
JOIN yak_security_menu menu_row
  ON menu_row.menu_code=permission_row.menu_code
 AND menu_row.app_name=role_permission.app_name
 AND menu_row.is_delete=0
 AND menu_row.active=1
WHERE role_permission.app_name='${appName}'
  AND role_permission.is_delete=0;

-- 补齐按钮所属菜单的父级目录。
INSERT IGNORE INTO yak_security_role_menu(role_id,menu_id,app_name)
SELECT DISTINCT role_menu.role_id,parent_menu.id,role_menu.app_name
FROM yak_security_role_menu role_menu
JOIN yak_security_menu child_menu
  ON child_menu.id=role_menu.menu_id
 AND child_menu.app_name=role_menu.app_name
 AND child_menu.is_delete=0
JOIN yak_security_menu parent_menu
  ON parent_menu.menu_code=child_menu.parent_code
 AND parent_menu.app_name=role_menu.app_name
 AND parent_menu.is_delete=0
 AND parent_menu.active=1
WHERE role_menu.app_name='${appName}'
  AND role_menu.is_delete=0
  AND child_menu.parent_code IS NOT NULL;

-- Source: data-ops-framework/data-security/src/main/resources/yak-security/db/migration/V3__evolve_message_center.sql
-- Expand yak_security_message into a general user notification inbox.
-- Existing rows remain valid and are treated as system/info notifications.

ALTER TABLE yak_security_message
  ADD COLUMN summary VARCHAR(255) NULL COMMENT '列表摘要' AFTER title,
  ADD COLUMN message_type VARCHAR(32) NOT NULL DEFAULT 'SYSTEM'
    COMMENT '消息类型：TASK/QUALITY/SECURITY/SYSTEM 等' AFTER content,
  ADD COLUMN message_level VARCHAR(16) NOT NULL DEFAULT 'INFO'
    COMMENT '消息级别：INFO/SUCCESS/WARNING/ERROR' AFTER message_type,
  ADD COLUMN message_scope VARCHAR(16) NOT NULL DEFAULT 'SYSTEM'
    COMMENT '消息范围：SYSTEM/PROJECT' AFTER message_level,
  ADD COLUMN project_id BIGINT NULL COMMENT '项目主键，系统消息为空' AFTER message_scope,
  ADD COLUMN source_type VARCHAR(64) NULL COMMENT '业务来源类型' AFTER project_id,
  ADD COLUMN source_id VARCHAR(128) NULL COMMENT '业务来源标识' AFTER source_type,
  ADD COLUMN action_path VARCHAR(512) NULL COMMENT '前端详情跳转路径' AFTER source_id,
  ADD COLUMN read_time TIMESTAMP NULL COMMENT '已读时间' AFTER read_tag,
  ADD KEY idx_message_app_user_read(app_name,user_id,read_tag,create_time),
  ADD KEY idx_message_app_user_project(app_name,user_id,project_id,create_time),
  ADD KEY idx_message_app_source(app_name,source_type,source_id);

-- Source: data-ops-boot/src/main/resources/yak-security/db/migration/V1000__init_yak_ops_security_catalog.sql
-- Yak Ops 自有业务权限与菜单初始化。
-- Yak Security 的用户、角色、系统管理权限和系统菜单由 yak-framework 维护。
-- 本目录只保留一个最终状态迁移，避免先创建历史目录再通过后续版本修正。

-- 1. 清理早期开发阶段已经移除的 Yak Ops 业务目录和授权关系。
UPDATE yak_security_role_menu role_menu
JOIN yak_security_menu menu_row
  ON menu_row.id = role_menu.menu_id
 AND menu_row.app_name = role_menu.app_name
SET role_menu.is_delete = 1
WHERE role_menu.app_name = '${appName}'
  AND menu_row.menu_code IN (
    'realtime-link-up',
    'workflow',
    'workflow-project',
    'workflow-management',
    'workflow-instance',
    'client',
    'connector',
    'quality',
    'data-quality',
    'data-quality-report',
    'operations',
    'metrics',
    'alarm',
    'knowledge-management'
  );

UPDATE yak_security_menu
SET active = 0,
    visible = 0,
    is_delete = 1
WHERE app_name = '${appName}'
  AND menu_code IN (
    'realtime-link-up',
    'workflow',
    'workflow-project',
    'workflow-management',
    'workflow-instance',
    'client',
    'connector',
    'quality',
    'data-quality',
    'data-quality-report',
    'operations',
    'metrics',
    'alarm',
    'knowledge-management'
  );

UPDATE yak_security_role_permission role_permission
JOIN yak_security_permission permission_row
  ON permission_row.id = role_permission.permission_id
 AND permission_row.app_name = role_permission.app_name
SET role_permission.is_delete = 1
WHERE role_permission.app_name = '${appName}'
  AND (
    permission_row.permission_code IN ('workflow', 'quality', 'operations', 'knowledge')
    OR permission_row.permission_code LIKE 'workflow:%'
    OR permission_row.permission_code LIKE 'task:realtime:%'
    OR permission_row.permission_code LIKE 'quality:%'
    OR permission_row.permission_code LIKE 'operations:%'
    OR permission_row.permission_code LIKE 'knowledge:%'
    OR permission_row.permission_code LIKE 'resource:client:%'
    OR permission_row.permission_code LIKE 'resource:connector:%'
  );

UPDATE yak_security_permission
SET active = 0,
    is_delete = 1
WHERE app_name = '${appName}'
  AND (
    permission_code IN ('workflow', 'quality', 'operations', 'knowledge')
    OR permission_code LIKE 'workflow:%'
    OR permission_code LIKE 'task:realtime:%'
    OR permission_code LIKE 'quality:%'
    OR permission_code LIKE 'operations:%'
    OR permission_code LIKE 'knowledge:%'
    OR permission_code LIKE 'resource:client:%'
    OR permission_code LIKE 'resource:connector:%'
  );

